SET search_path TO imperial, public;
-- Add only the independently controllable quotation-fee permission; existing keys and validation remain intact.
CREATE OR REPLACE FUNCTION valid_permission_overrides(value jsonb) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$
 SELECT CASE WHEN jsonb_typeof(value)<>'object' THEN false ELSE NOT EXISTS (SELECT 1 FROM jsonb_each_text(value) AS entry WHERE entry.key NOT IN ('ar.read','ar.generate','ar.aging','ar.overdue','ar.due','ar.paid','ar.customer','ar.followups','ar.followup.add','ar.promise','ar.promise.edit','ar.credit','ar.credit.edit','ar.statement','ar.adjust','collections.read','collections.record','collections.details','collections.accounts','collections.reverse','collections.checks','collections.check.update','collections.summary','quotations.read','quotations.create','quotations.fees','quotations.edit','quotations.approve','quotations.convert','orders.read','orders.create','orders.edit','orders.confirm','orders.cancel','deliveries.read','deliveries.create','deliveries.assign','deliveries.finalize','invoices.read','invoices.create','invoices.assign','invoices.finalize','commercial.read','commercial.prices','commercial.cancel','customers.read','customers.write','customers.credit','products.read','products.write','products.cost','products.prices','suppliers.read','suppliers.write','inventory.read','inventory.receive','inventory.issue','inventory.value','sales.read','sales.create','sales.edit','sales.post','sales.prices','sales.override','sales.discounts','sales.discount.apply','sales.payments','sales.payment.edit','sales.cogs','sales.profit','sales.margin','sales.documents','sales.documents.require','sales.si.assign','sales.dr.assign','sales.si.print','sales.dr.print','sales.documents.void','sales.cancel','customers.create','customers.edit','returns.read','returns.create','returns.approve','returns.receive','returns.condition','returns.restock','returns.reject','returns.complete','returns.financial') OR entry.value IS NULL OR entry.value NOT IN ('allow','deny')) END
$$;
